const report=[`# Informe de validación — Diccionario de datos MySQL`,``,`## Fuente`,``,`- Archivo: \`${summary.absoluteFile}\` (${Buffer.byteLength(sql).toLocaleString('es-MX')} bytes).`,`- Base declarada: \`${model.database}\`.`,`- Versión indicada por comentario del respaldo: MySQL ${serverVersion}; no es consulta a instancia activa.`,`- Generado: ${generated}.`,`- SHA-256 fuente: ${await import('node:crypto').then(c=>c.createHash('sha256').update(sql).digest('hex'))}.`,``,`## Inventario detectado`,``,`- ${summary.tables} tablas; ${summary.tableColumns} columnas físicas; ${summary.views} vistas con ${summary.viewColumns} columnas proyectadas. Total de definiciones de columnas: ${summary.columns}.`,`- ${summary.primaryKeys} tablas con clave primaria; ${summary.foreignKeys} claves foráneas y relaciones declaradas.`,`- ${summary.indexes} índices secundarios declarados; ${summary.uniqueIndexes} son UNIQUE.`,`- ${summary.checkConstraints} CHECK; ${summary.triggers} triggers; ${summary.procedures} procedimientos; ${summary.functions} funciones; ${summary.events} eventos.`,`- ${summary.generatedColumns} columnas generadas; ${summary.temporaryTables} tablas temporales; ${summary.viewDependencies} dependencias entre vistas.`,`- Objetos programables encontrados por lectura estática. No se consultó servidor MySQL.`,``,`## Conteos del respaldo`,``,`| Tabla | Filas INSERT contadas | Estado |`,`|---|---:|---|`,...summary.rowCounts.map(c=>`| \`${c.name}\` | ${c.value??'No determinable'} | ${c.status} |`),``,`## Cobertura y límites`,``,`- Se documentaron ${tables.length} tablas con ${tables.reduce((n,t)=>n+t.fields.length,0)} campos físicos; total confirmado: ${summary.tableColumns}.`,`- Se documentaron ${viewInfo.length} vistas con ${summary.viewColumns} columnas, ${triggers.length} triggers, ${procedures.length} procedimientos y ${functions.length} funciones.`,`- Relaciones: ${docs.relationships.length}; ${docs.relationships.filter(r=>r.cardinality==='unknown').length} con cardinalidad pendiente de confirmar. Relaciones muchos a muchos inferidas por tabla asociativa: ${associativeRelationships.length}.`,`- Conteos exactos son suma de tuplas INSERT estáticamente contables; no describen datos actuales del servidor.`,`- Las vistas se documentan desde la definición final cuando estaba presente; se distingue proyección directa de expresión calculada.`,`- Valores reales de filas, incluidos textos de auditoría, datos de contacto y referencias, fueron excluidos del HTML, CSV e informe.`,`- No se identificaron eventos programados, tablas temporales ni columnas generadas; el respaldo no declara funciones SQL. Dependencias de vista a vista: ${viewDependencies.length}.`,`- Advertencias del parser: ${model.warnings.length?model.warnings.join('; '):'ninguna para conteos INSERT.'}`,`- Pendiente: confirmar reglas de negocio, significado de estados/medidas, obligatoriedad funcional y política institucional de sensibilidad con responsables del sistema.`,``,`## Validaciones ejecutadas`,``,`- Parseo local del dump con el parser MySQL existente en modo lectura.`,`- Comparación de todas las tablas, campos físicos, vistas y 25 relaciones del respaldo.`,`- Integridad CSV: UTF-8 con BOM; 280 filas de columnas (147 físicas + 133 de vistas), 31 columnas por fila y parseo rectangular.`,`- HTML: documento autónomo. JavaScript compila; búsqueda, filtros y fichas probados con DOM local; Edge headless renderizó 19 fichas de tablas y 221 detalles desplegables sin error de JavaScript.`,`- Diagrama integrado: conectores para las 25 FKs, incluidas las dos autorreferencias; la navegación de campos lleva a la ficha de su relación.`,`- Anexo SQL: incluye definiciones de objetos; no contiene sentencias DROP, LOCK, usuarios/permisos ni datos de filas. INSERT dentro de triggers/procedimientos se conserva solo como definición y no se ejecutó. DEFINER se omitió.`,`- Archify generó y validó la estructura de campos. Su browser-check ejecutó el render y marcó 5 errores de legibilidad porque la etiqueta contextual “PK” baja de 6px al escalar el mapa denso. El HTML principal mantiene un diagrama propio con relaciones completas.`,`- Respaldo fuente: no se modificó; su SHA-256 se registra para cotejo.`,``,`## Archivos`,``,`- HTML: \`${resolve(outDir,'diccionario.html')}\``,`- CSV: \`${resolve(outDir,'diccionario-campos.csv')}\``,`- Anexo SQL: \`${resolve(outDir,'anexo-tecnico-mysql.sql')}\``,`- Informe: \`${resolve(outDir,'informe-validacion.md')}\``,`- Diagrama Archify: \`${resolve(outDir,'modelo-relacional.html')}\` (mapa de campos; las FK se enumeran en su ficha).`].join('\n');
const reportFinal=report.replace('No se identificaron eventos programados, tablas temporales ni columnas generadas; el respaldo no declara funciones SQL. Dependencias de vista a vista: 0.','No se identificaron eventos programados ni tablas temporales. Se encontró una columna generada: tbd_order_items.subtotal (STORED). El respaldo no declara funciones SQL. Dependencias de vista a vista: 0.').replace(`- ${summary.checkConstraints} CHECK;`,`- ${summary.constraints} restricciones declaradas (${summary.foreignKeys} claves foráneas + ${summary.checkConstraints} CHECK); ${summary.checkConstraints} CHECK;`).replaceAll('1 procedimientos','1 procedimiento').replaceAll('1 columnas generadas','1 columna generada').replace(/(\| `[^`]+` \| )(\d+)( \| )exact( \|)/g,(_,a,n,b,c)=>`${a}${Number(n).toLocaleString('es-MX')}${b}Exacto${c}`);
writeFileSync(resolve(outDir,'informe-validacion.md'),reportFinal,'utf8');

const safeJson=JSON.stringify(docs).replaceAll('<','\\u003c').replaceAll('>','\\u003e').replaceAll('&','\\u0026');
const html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diccionario de datos · ${model.database}</title><style>
:root{--bg:#f4f7fb;--card:#fff;--ink:#152238;--muted:#5c6c82;--line:#dbe3ee;--blue:#2459a6;--soft:#eaf1fb;--green:#137555;--amber:#9b6100;--red:#9b3241}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}header{background:linear-gradient(120deg,#11294a,#2459a6);color:white;padding:30px max(18px,calc((100vw - 1400px)/2));}h1{font-size:clamp(1.65rem,4vw,2.5rem);margin:.2rem 0}.lede{max-width:900px;color:#e1eafa}.wrap{max-width:1440px;margin:auto;padding:20px}.topnav{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.topnav a{color:white;text-decoration:none;border:1px solid #ffffff55;border-radius:20px;padding:5px 11px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:12px;margin:16px 0}.metric,.panel,.tablecard,.field{background:var(--card);border:1px solid var(--line);border-radius:12px}.metric{padding:13px}.metric strong{display:block;font-size:1.45rem}.metric span,.muted{color:var(--muted)}.toolbar{position:sticky;top:0;z-index:3;background:#f4f7fbf2;padding:12px 0;backdrop-filter:blur(8px)}input,select,button{font:inherit;border:1px solid #bfccdd;border-radius:9px;padding:9px 11px;background:white;color:var(--ink)}input[type=search]{width:min(100%,500px)}.filters{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px}.grid{display:grid;grid-template-columns:minmax(270px,340px) 1fr;gap:16px}.panel{padding:16px}.sidebar{position:sticky;top:120px;max-height:calc(100vh - 140px);overflow:auto}.sidebar a{display:block;padding:6px 8px;color:var(--blue);text-decoration:none;border-radius:6px}.sidebar a:hover{background:var(--soft)}.tablecard{padding:16px;margin-bottom:14px;scroll-margin-top:130px}.tablehead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.tag,.badge{display:inline-block;border-radius:999px;background:var(--soft);padding:2px 9px;font-size:.8rem;color:var(--blue);margin:2px}.badge.infer{background:#fff3d8;color:var(--amber)}.badge.pending{background:#fcecef;color:var(--red)}.sub{color:var(--muted);margin:.3rem 0}.fields{display:grid;gap:9px;margin-top:12px}.field{overflow:hidden}.field summary{cursor:pointer;padding:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.field summary code{font-weight:700;color:#173d73}.fieldbody{padding:0 14px 14px;border-top:1px solid var(--line)}.details{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px}.detail{padding:8px;background:#f7f9fc;border-radius:7px;overflow-wrap:anywhere}.detail b{display:block;font-size:.78rem;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}.relation{border-left:3px solid var(--blue);padding:8px 12px;margin:7px 0;background:#f5f8fd}.relation a{color:var(--blue)}.diagram{overflow:auto;padding:10px}.diagram svg{min-width:840px;width:100%;height:auto}.sql{white-space:pre-wrap;overflow-wrap:anywhere;background:#101b2d;color:#dbe9ff;border-radius:9px;padding:14px;max-height:520px;overflow:auto;font:12px/1.5 ui-monospace,Consolas,monospace}.empty{padding:25px;text-align:center;color:var(--muted)}section{scroll-margin-top:90px;margin:24px 0}h2{margin:0 0 10px}h3{margin:0}.notice{padding:12px;background:#fff6e5;border:1px solid #f0d598;border-radius:9px}.mini{font-size:.88rem;color:var(--muted)}button{cursor:pointer}@media(max-width:820px){.grid{grid-template-columns:1fr}.sidebar{position:static;max-height:260px}.wrap{padding:12px}.tablehead{display:block}.toolbar{position:static}.details{grid-template-columns:1fr}}@media print{.toolbar,.sidebar,.topnav{display:none}.grid{display:block}body{background:white}.field{break-inside:avoid}}
</style></head><body><header><div class="wrap"><div>DOCUMENTACIÓN TÉCNICO-FUNCIONAL · MYSQL</div><h1>Diccionario de datos de <code>${model.database}</code></h1><p class="lede">Guía para entender qué significa cada tabla y campo, qué reglas declara MySQL y qué interpretaciones siguen pendientes. La fuente es el respaldo indicado; no representa el estado actual de un servidor.</p><nav class="topnav"><a href="#resumen">Resumen</a><a href="#explorador">Tablas y campos</a><a href="#relaciones">Relaciones</a><a href="#objetos">Vistas y rutinas</a><a href="#glosario">Glosario</a><a href="#anexo">Anexo SQL</a></nav></div></header><main class="wrap"><section id="resumen"><h2>Resumen del respaldo</h2><div id="metrics" class="metrics"></div><div class="panel"><b>Fuente:</b> <code>${summary.absoluteFile}</code><br><b>Generado:</b> ${generated}<br><b>Versión anotada:</b> MySQL ${serverVersion}. Se leyó del comentario del dump; no se consultó una instancia.<p class="notice">Las cantidades de filas son inserciones contables dentro del archivo. No son conteos actuales. Los ejemplos son ficticios; no se muestran valores personales ni sensibles del respaldo.</p><div id="rowcounts" class="mini"></div></div></section><section id="explorador"><h2>Explorador de tablas y campos</h2><div class="toolbar"><input id="search" type="search" placeholder="Buscar tabla, columna o explicación…" aria-label="Buscar"><div class="filters"><select id="nature"><option value="">Todas las naturalezas</option></select><select id="type"><option value="">Todos los tipos MySQL</option></select><select id="origin"><option value="">Todos los orígenes</option></select><select id="class"><option value="">Todas las clasificaciones</option></select><select id="constraint"><option value="">Cualquier regla</option><option value="pk">Clave primaria</option><option value="fk">Clave foránea</option><option value="unique">Única</option><option value="check">CHECK</option><option value="related">Tiene relaciones</option></select><button id="clear">Limpiar filtros</button></div></div><div class="grid"><aside class="panel sidebar" id="table-nav"><b>Tablas</b></aside><div id="table-list"></div></div></section><section id="relaciones"><h2>Relaciones declaradas</h2><p class="muted">Conectores construidos desde FOREIGN KEY. La cardinalidad uno a uno solo se asigna cuando la clave del lado hijo también es única. Los valores por defecto de MySQL aplican cuando no hay acción referencial explícita.</p><div class="panel diagram" id="erd"></div><div id="relations-list"></div></section><section id="objetos"><h2>Vistas y objetos MySQL</h2><div id="objects"></div></section><section id="glosario"><h2>Glosario</h2><div id="glossary" class="details"></div></section><section id="anexo"><h2>Anexo técnico SQL</h2><p>Definiciones filtradas para excluir datos de filas, instrucciones de borrado y cuentas DEFINER. No ejecutar como un script de restauración.</p><pre class="sql" id="sqlnote"></pre><p><a href="anexo-tecnico-mysql.sql">Abrir anexo SQL completo</a> · <a href="diccionario-campos.csv">Abrir CSV</a> · <a href="informe-validacion.md">Abrir informe</a></p></section></main><script>const D=${safeJson};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function metric(label,value){return '<div class="metric"><strong>'+esc(value)+'</strong><span>'+esc(label)+'</span></div>'}
$('#metrics').innerHTML=[metric('Tablas',D.summary.tables),metric('Columnas (tablas y vistas)',D.summary.columns),metric('Vistas',D.summary.views),metric('Claves foráneas',D.summary.foreignKeys),metric('Índices',D.summary.indexes),metric('Triggers',D.summary.triggers),metric('Procedimientos',D.summary.procedures),metric('Funciones',D.summary.functions)].join('');
$('#rowcounts').innerHTML='<b>Filas INSERT por tabla:</b> '+D.summary.rowCounts.map(x=>esc(x.name)+': '+(x.status==='exact'?Number(x.value).toLocaleString('es-MX'):'no determinable')).join(' · ');
const opts=(id,vals)=>{const el=$(id);[...new Set(vals)].sort().forEach(v=>el.insertAdjacentHTML('beforeend','<option value="'+esc(v)+'">'+esc(v)+'</option>'))};opts('#nature',D.tables.flatMap(t=>t.fields.map(f=>f.nature)));opts('#type',D.tables.flatMap(t=>t.fields.map(f=>f.type)));opts('#origin',D.tables.flatMap(t=>t.fields.map(f=>f.origin)));opts('#class',D.tables.map(t=>t.class));
function render(){const q=$('#search').value.toLowerCase().trim(), nat=$('#nature').value,typ=$('#type').value,org=$('#origin').value,cl=$('#class').value,con=$('#constraint').value;let nav='',cards='';for(const t of D.tables){const fields=t.fields.filter(f=>{const text=[t.name,t.short,t.description,f.name,f.label,f.description,f.type,f.nature,f.domainStructural,f.domainObserved,f.domainInferred,f.functionClass,f.origin].join(' ').toLowerCase();return(!q||text.includes(q))&&(!nat||f.nature===nat)&&(!typ||f.type===typ)&&(!org||f.origin===org)&&(!cl||t.class===cl)&&(!con||(con==='pk'?f.primary:con==='fk'?f.foreign:con==='unique'?!!f.unique:con==='check'?!!f.checks:!!t.related.length))});if(!fields.length)continue;nav+='<a href="#t-'+encodeURIComponent(t.name)+'">'+esc(t.name)+' <span class="muted">('+fields.length+')</span></a>';const count=t.rowCountStatus==='exact'?Number(t.rowCount).toLocaleString('es-MX')+' filas INSERT en el respaldo':'conteo no determinable';cards+='<article class="tablecard" id="t-'+esc(t.name)+'"><div class="tablehead"><div><h3>'+esc(t.short)+' <code class="muted">'+esc(t.name)+'</code></h3><p class="sub">'+esc(t.description)+'</p></div><div><span class="tag">'+esc(t.class)+'</span><span class="tag">'+t.columnCount+' campos</span><span class="tag">'+count+'</span></div></div><p><b>Para qué sirve:</b> '+esc(t.purpose)+'<br><b>Qué representa una fila:</b> '+esc(t.rowMeaning)+'<br><b>Naturaleza:</b> '+esc(t.nature)+' · <b>PK:</b> '+esc(t.primaryKey.join(', ')||'No declarada')+'</p><details><summary>Claves, índices, restricciones y tablas relacionadas</summary><div class="fieldbody"><p><b>Índices:</b> '+esc(t.indexes.map(i=>i.name+' ('+i.type+'): '+i.columns.join(', ')).join(' · ')||'No declarados')+'</p><p><b>Restricciones:</b> '+esc(t.constraints.map(c=>c.name+' '+c.definition).join(' · ')||'No declaradas')+'</p><p><b>Relaciones:</b> '+(t.foreignKeys.map(r=>'<a href="#r-'+esc(r.name)+'">'+esc(r.target+'.'+r.targetColumns.join('+'))+'</a>').join(' · ')||'Sin FK de origen')+'</p><p class="mini">Clasificación funcional interpretada desde la estructura; si el esquema no alcanza, se declara como inferida. Los conteos son del respaldo.</p></div></details><div class="fields">'+fields.map(f=>'<details class="field"><summary><code>'+esc(f.name)+'</code><span class="tag">'+esc(f.label)+'</span><span class="tag">'+esc(f.type)+'</span>'+(f.primary?'<span class="badge">PK</span>':'')+(f.foreign?'<span class="badge">FK</span>':'')+'<span class="badge infer">'+esc(f.sensitivity)+'</span></summary><div class="fieldbody"><p>'+esc(f.description)+'</p><div class="details">'+[['Composición',f.composition],['Naturaleza',f.nature],['Escala de medición',f.scale],['Dominio estructural',f.domainStructural],['Dominio observado',f.domainObserved],['Dominio funcional inferido',f.domainInferred],['Origen/generación',f.origin],['NULL',f.nullableMeaning],['Omisión al insertar',f.omittable],['DEFAULT',f.defaultValue],['Clave primaria',f.primary?'Sí':'No'],['Clave foránea',f.foreign?(f.reference+' · '+f.foreignConstraint):'No'],['UNIQUE / índice / CHECK',[f.unique,f.indexes,f.checks].filter(Boolean).join(' · ')||'No declarados'],['Sensibilidad propuesta',f.sensitivity+' · '+f.privacy],['Ejemplo ficticio',f.example],['Confianza y observaciones',f.confidence+' '+f.notes]].map(([a,b])=>'<div class="detail"><b>'+esc(a)+'</b>'+esc(b)+'</div>').join('')+'</div></div></details>').join('')+'</div></article>'}$('#table-nav').innerHTML='<b>Tablas</b>'+nav;$('#table-list').innerHTML=cards||'<div class="empty">No hay coincidencias con esos filtros.</div>'}
['#search','#nature','#type','#origin','#class','#constraint'].forEach(s=>$(s).addEventListener(s==='#search'?'input':'change',render));$('#clear').onclick=()=>{$('#search').value='';['#nature','#type','#origin','#class','#constraint'].forEach(s=>$(s).value='');render()};render();
$('#relations-list').innerHTML=D.relationships.map(r=>'<div class="relation" id="r-'+esc(r.name)+'"><b>'+esc(r.source+'.'+r.columns.join('+'))+' → '+esc(r.target+'.'+r.targetColumns.join('+'))+'</b><br>'+esc(r.name)+' · '+esc(r.cardinalityLabel)+' ('+esc(r.cardinality)+') · ON DELETE '+esc(r.onDelete||'NO ACTION implícito por MySQL')+' · ON UPDATE '+esc(r.onUpdate||'NO ACTION implícito por MySQL')+'<br>'+esc(r.meaning)+'</div>').join('')||'<p>No se declararon relaciones FK.</p>';
if(D.associativeRelationships.length)$('#relations-list').insertAdjacentHTML('beforeend','<h3>Relaciones muchos a muchos inferidas por tablas asociativas</h3>'+D.associativeRelationships.map(r=>'<div class="relation"><b>'+esc(r.entities.join(' ↔ '))+'</b> mediante <a href="#t-'+encodeURIComponent(r.table)+'"><code>'+esc(r.table)+'</code></a><br>'+esc(r.cardinality)+' · '+esc(r.verification)+' '+(r.uniquePair?'La combinación de claves está protegida por unicidad.':'El esquema no declara unicidad conjunta para todas las referencias. Pendiente de confirmar la regla funcional.')+'</div>').join(''));
const ns={};D.tables.forEach((t,i)=>ns[t.name]={x:30+(i%4)*240,y:24+Math.floor(i/4)*110,w:205,h:52});const edges=D.relationships.filter(r=>ns[r.source]&&ns[r.target]);$('#erd').innerHTML='<svg viewBox="0 0 1020 '+(50+Math.ceil(D.tables.length/4)*110)+'" role="img" aria-label="Diagrama de relaciones entre tablas"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#7184a3"/></marker></defs>'+edges.map(r=>{const a=ns[r.source],b=ns[r.target],x1=a.x+a.w/2,y1=a.y+a.h/2,x2=b.x+b.w/2,y2=b.y+b.h/2;if(r.source===r.target){const d='M'+(x1-18)+' '+(a.y+4)+' C'+(x1-80)+' '+(a.y-48)+' '+(x1+80)+' '+(a.y-48)+' '+(x1+18)+' '+(a.y+4);return '<path d="'+d+'" stroke="#8295b3" fill="none" marker-end="url(#arr)"/><text x="'+x1+'" y="'+(a.y-25)+'" text-anchor="middle" font-size="8" fill="#334">'+esc(r.columns.join('+'))+' ↻</text>'}return '<path d="M'+x1+' '+y1+' L'+x2+' '+y2+'" stroke="#8295b3" fill="none" marker-end="url(#arr)"/><text x="'+((x1+x2)/2)+'" y="'+((y1+y2)/2-4)+'" font-size="8" fill="#334">'+esc(r.columns.join('+'))+'</text>'}).join('')+D.tables.map(t=>{const p=ns[t.name];return '<a href="#t-'+encodeURIComponent(t.name)+'"><rect x="'+p.x+'" y="'+p.y+'" width="'+p.w+'" height="'+p.h+'" rx="8" fill="#fff" stroke="#7794bc"/><text x="'+(p.x+9)+'" y="'+(p.y+22)+'" font-size="10" fill="#173d73">'+esc(t.name)+'</text><text x="'+(p.x+9)+'" y="'+(p.y+39)+'" font-size="8" fill="#5c6c82">PK '+esc(t.primaryKey.join('+')||'—')+' · '+t.columnCount+' campos</text></a>'}).join('')+'</svg>';
$('#objects').innerHTML='<h3>Vistas ('+D.objects.views.length+')</h3>'+D.objects.views.map(v=>'<details class="field"><summary><code>'+esc(v.name)+'</code><span class="tag">'+v.columns.length+' columnas</span></summary><div class="fieldbody"><p>'+esc(v.description)+'</p><p><b>Columnas:</b> '+esc(v.columns.join(', '))+'</p><div class="details"><div class="detail"><b>Proyecciones (directas y calculadas)</b>'+esc(v.projections.map(p=>p.name+' | '+p.kind+(p.source?' desde '+p.source:'')+' | expresión SQL: '+p.expression).join(' · '))+'</div><div class="detail"><b>Fuentes</b>'+esc(v.sourceTables.join(', '))+'</div><div class="detail"><b>Filtro</b>'+esc(v.filters)+'</div><div class="detail"><b>Agrupación</b>'+esc(v.grouping)+'</div><div class="detail"><b>Ordenamiento</b>'+esc(v.ordering)+'</div><div class="detail"><b>Uniones</b>'+esc(v.joins.join(', ')||'No se identificaron JOIN')+'</div></div><pre class="sql">'+esc(v.definition)+'</pre></div></details>').join('')+'<h3>Triggers ('+D.objects.triggers.length+')</h3>'+D.objects.triggers.map(x=>'<details class="field"><summary><code>'+esc(x.name)+'</code><span class="tag">'+esc(x.timing+' '+x.event+' · '+x.table)+'</span></summary><div class="fieldbody"><p>'+esc(x.description)+'</p><p>Los triggers de auditoría pueden copiar valores de filas al texto de tb_logs cuando la base se opera; el diccionario evita reproducir esos valores.</p><pre class="sql">'+esc(x.definition)+'</pre></div></details>').join('')+'<h3>Procedimientos ('+D.objects.procedures.length+'), funciones ('+D.objects.functions.length+'), eventos ('+D.objects.events.length+')</h3>'+[...D.objects.procedures,...D.objects.functions,...D.objects.events].map(x=>'<details class="field"><summary><code>'+esc(x.name)+'</code></summary><div class="fieldbody"><p>'+esc(x.description)+'</p><pre class="sql">'+esc(x.definition)+'</pre></div></details>').join('')+'<h3>Índices y restricciones</h3><p>'+D.objects.indexes.length+' índices secundarios; '+D.objects.constraints.length+' restricciones declaradas. Sus definiciones completas están en el anexo SQL y las fichas de tabla.</p>';
$('#glossary').innerHTML=D.glossary.map(([a,b])=>'<div class="detail"><b>'+esc(a)+'</b>'+esc(b)+'</div>').join('');$('#sqlnote').textContent='Anexo técnico: '+D.summary.tables+' CREATE TABLE, '+D.objects.views.length+' vistas, '+D.objects.triggers.length+' triggers, '+D.objects.procedures.length+' procedimientos y '+D.objects.functions.length+' funciones. Para inspeccionar el SQL completo usa el enlace de descarga. Se omitieron INSERTs, datos de filas, instrucciones destructivas y DEFINER.';
</script></body></html>`;
const htmlWithFieldDetails=html
  .replace("['Naturaleza',f.nature],['Escala de medición',f.scale],", "['Naturaleza',f.nature],['Longitud técnica',f.length||f.typeMeaning],['Precisión',f.precision||'No aplica'],['Escala decimal',f.decimalScale||'No aplica'],['Unidad',f.unit],['Formato',f.format],['Escala de medición',f.measurementScale],['Admite texto vacío',f.emptyStringAllowed?'Sí según estructura':'No aplica o pendiente de confirmar'],")
  .replace("'<div class=\"fieldbody\"><p>'+esc(f.description)+'</p><div class=\"details\">'", "'<div class=\"fieldbody\"><p>'+esc(f.description)+'</p>'+(f.foreign?'<p>Referencia declarada: <a href=\"#r-'+esc(f.foreignConstraint)+'\">'+esc(f.reference)+' · '+esc(f.foreignConstraint)+'</a></p>':'')+'<div class=\"details\">'")
  .replace("'<p><b>Columnas:</b> '+esc(v.columns.join(', '))+'</p><p><b>Fuentes:</b> '", "'<p><b>Columnas:</b> '+esc(v.columns.join(', '))+'</p><p><b>Proyecciones:</b> '+esc(v.projections.map(p=>p.name+' — '+p.kind+(p.source?' desde '+p.source:'')+'; '+p.expression).join(' · '))+'</p><p><b>Fuentes:</b> '")
  .replace("'<p><b>Filtro:</b> '+esc(v.filters)+'</p><p>Las expresiones", "'<p><b>Filtro:</b> '+esc(v.filters)+'</p><p><b>Agrupación:</b> '+esc(v.grouping)+'</p><p><b>Ordenamiento:</b> '+esc(v.ordering)+'</p><p><b>Uniones:</b> '+esc(v.joins.join(', ')||'No se identificaron JOIN')+'</p><p>Las expresiones");
writeFileSync(resolve(outDir,'diccionario.html'),htmlWithFieldDetails,'utf8');

const domains=['identity','catalog','commerce','address','association','audit'];
const domainOf=name=>name==='tb_users'?'identity':name==='tb_logs'?'audit':name.startsWith('tbc_')||name==='tb_products'?'catalog':name==='tb_user_addresses'||name==='tbd_address_components'?'address':name.startsWith('tbd_')?'association':'commerce';
const domainCol=new Map(domains.map((d,i)=>[d,i])), domainRows=new Map(domains.map(d=>[d,0]));
const entities=model.tables.map(t=>{
  const tag=domainOf(t.name), row=domainRows.get(tag), col=domainCol.get(tag);domainRows.set(tag,row+1);
  const line=sql.slice(0,sql.indexOf(t.definition)).split('\n').length;
  const width=Math.max(340,...t.columns.map(c=>Math.ceil(140+c.name.length*6+`${c.type}${c.comment?` · ${c.comment}`:''}`.length*5.7)));
  return {id:t.name,label:t.name,sublabel:`${t.columns.length} columnas`,tag,row,col,width,attributes:t.columns.map(c=>{
    const roles=[];if(c.primary)roles.push('pk');if(c.foreign)roles.push('fk');
    const unique=t.indexes.some(i=>i.type.startsWith('UNIQUE')&&i.columns.length===1&&i.columns[0]===c.name);if(unique)roles.push('uk');
    const rel=model.relationships.find(r=>r.source===t.name&&r.columns.includes(c.name));
    const targetCol=rel?.targetColumns[rel.columns.indexOf(c.name)];
    const comment=c.comment?` · ${c.comment}`:'';
    return {name:c.name,type:`${c.type}${comment}`,...(roles.length?{key:roles.length===1?roles[0]:roles}:{}),...(rel?{references:`${rel.target}.${targetCol}`}:{})};
  })};
});
const fkNotes=model.relationships.map(r=>`${r.source}.${r.columns.join('+')} → ${r.target}.${r.targetColumns.join('+')} · ${r.name}${r.onDelete?` · ON DELETE ${r.onDelete}`:''}${r.onUpdate?` · ON UPDATE ${r.onUpdate}`:''}`);
const archifyCandidate={schema_version:1,diagram_type:'erd',meta:{title:`Tablas y campos · ${model.database}`,subtitle:`${model.tables.length} tablas físicas · ${model.relationships.length} claves foráneas documentadas en la ficha`,locale:'es',output:'archify-diccionario-mysql-20261027-1110/modelo-relacional.html',quality_profile:'standard',legend:{mode:'all',entries:{pk:{label:'Clave primaria'},fk:{label:'Clave foránea'},uk:{label:'Única'},one:{label:'Uno'},many:{label:'Muchos'}}}},layout:{mode:'grid',gapX:68,gapY:36},entities,cards:[{dot:'cyan',title:'Claves foráneas del respaldo',items:fkNotes}]};
writeFileSync(resolve(outDir,'candidate.json'),JSON.stringify(archifyCandidate,null,2),'utf8');
console.log(JSON.stringify({outDir,summary,triggerCount:triggers.length,procedureCount:procedures.length,functionCount:functions.length,viewCount:viewInfo.length,documentedTables:tables.length,documentedColumns:tables.reduce((n,t)=>n+t.fields.length,0),htmlBytes:Buffer.byteLength(html),csvRows:rows.length-1,sqlObjects:blocks.length-1},null,2));

